  add('grammar','basic','次のうち、形容詞はどれですか。','高い',['山','走る','ゆっくり'],['「どんなだ」にあたる言葉をさがします。','言い切るとき、「い」で終わる言葉です。'],'「高い」はようすを表す言葉（形容詞）です。「山」は名詞、「走る」は動詞です。');
  add('grammar','basic','人が話した言葉を書くときに使う記号は何ですか。','かぎ（「　」）',['読点（、）','句点（。）','中点（・）'],['会話文を書くときに使います。','話した言葉を、前後ではさみます。'],'人が話した言葉は、かぎ（「　」）ではさんで書きます。');
  add('grammar','basic','「あしたは 雨でしょうか。」は、何を表す文ですか。','質問',['命令','おどろき','お願い'],['文の終わりの言葉に注目します。','答えをたずねる文です。'],'「あしたは雨でしょうか。」は、相手に答えをたずねる、質問の文です。');

  add('grammar','standard','「ぼくが 作った ケーキを 妹が 食べた。」の主語は何ですか。','妹が',['ぼくが','ケーキを','作った'],['文の終わりの「食べた」の主語をさがします。','「だれが」食べたのでしょう。'],'この文では、「食べた」の主語は「妹が」です。「ぼくが」は「作った」の主語です。');
  add('grammar','standard','「きのう 友だちと 公園で サッカーを した。」の「どこで」にあたる言葉は何ですか。','公園で',['友だちと','きのう','サッカーを'],['場所を表す言葉をさがします。','「で」がついています。'],'「公園で」が、「どこで」にあたる言葉です。',null,['こうえんで','公園で']);
  add('grammar','standard','「赤い 小さな 花が さく。」の「小さな」は、どの言葉をくわしくしていますか。','花が',['赤い','さく','小さな'],['「小さな」ものは、何でしょう。','「小さな」のすぐあとの言葉に注目します。'],'「小さな」は、「どんな」花なのかを説明して、「花が」をくわしくしています。');
  add('grammar','standard','「しかし」のように、前の文とあとの文をつなぐはたらきをする言葉を、何といいますか。','接続語',['主語','述語','修飾語'],['文と文をつなぎます。','「だから」「そして」なども、同じなかまです。'],'前の文とあとの文をつなぐ言葉を、接続語といいます。',null,['せつぞくご','接続語']);
  add('grammar','standard','「はい」「ああ」のように、ほかの言葉と関係なく、独立して使われる言葉を、何といいますか。','独立語',['主語','述語','接続語'],['返事やよびかけ、おどろきなどを表します。','文の中で、ほかの言葉とのつながりがありません。'],'ほかの言葉とのつながりをもたず、独立して使われる言葉を、独立語といいます。');
  add('grammar','standard','「花が さく。」の「さく」は、文の中で何といいますか。','述語',['主語','修飾語','接続語'],['「どうする」にあたる言葉です。','文の終わりにある言葉です。'],'「さく」は、「どうする」を表す、述語です。',null,['じゅつご','述語']);
  add('grammar','standard','「ドアがあく」と「ドアをあける」のうち、人が動作をはたらきかける言い方はどちらですか。','ドアをあける',['ドアがあく','どちらも同じ','どちらでもない'],['「～が」と「～を」の使い分けを考えます。','だれかが、ドアに、はたらきかけています。'],'「ドアをあける」は、人がドアにはたらきかける言い方です。「ドアがあく」は、ひとりでに起こることを表します。');
  add('grammar','standard','「雨にふられた」の「られた」は、どんな意味を表していますか。','受け身',['できる','尊敬','自然に起こる'],['雨が、ふったことで、どうなりましたか。','動作を受ける側から言う言い方です。'],'「雨にふられた」の「られた」は、動作を受けることを表す、受け身の言い方です。');
  add('grammar','standard','「ぼくの 好きな 食べものは、カレーだ。」の述語は何ですか。','カレーだ',['好きな','ぼくの','食べものは'],['文の終わりにある言葉をさがします。','「食べものは」どうなのでしょう。'],'この文では、「食べものは」に対応する「カレーだ」が述語です。',null,['カレーだ']);
  add('grammar','standard','「寒いのに、はんそでを着ている。」の「のに」は、どんな関係を表していますか。','予想とはちがうことが起こる関係',['理由を表す関係','ならべて言う関係','場所を表す関係'],['寒いと、ふつうは、どんな服を着るでしょう。','ふつうとはちがうことを、言っています。'],'「のに」は、予想とはちがうことが起こったときに使います。');
  add('grammar','standard','「かぜをひかないように、手をあらう。」の「ように」は、何を表していますか。','目的',['たとえ','場所','理由'],['何のために、手をあらうのでしょう。','「～のために」と言いかえられます。'],'「かぜをひかないように」は、手をあらう目的を表しています。');
  add('grammar','standard','次のうち、述語が二つある文はどれですか。','ぼくが歌い、妹がおどった。',['ぼくが歌った。','妹がおどる。','雪がふる。'],['「歌い」と「おどった」に注目します。','二つの動作が、一つの文の中にあります。'],'「ぼくが歌い、妹がおどった。」には、「歌い」と「おどった」の二つの述語があります。');

  add('grammar','advanced','「雪がふっている 朝、ぼくは 学校へ 行った。」の「行った」の主語は何ですか。','ぼくは',['雪が','朝','学校へ'],['「だれが」行ったのでしょう。','「雪が」は、「ふっている」の主語です。'],'「行った」の主語は「ぼくは」です。「雪が」は「ふっている」の主語です。');
  add('grammar','advanced','「けっして」と合う、文の終わり方は何ですか。','ない',['です','だろう','たい'],['「けっして」のあとは、打ち消しになります。','「けっして ～ ない」の形で使います。'],'「けっして」は、「～ない」という打ち消しの言い方と、いっしょに使います。',null,['ない']);
  add('grammar','advanced','「まるで」と合う、文の終わり方はどれですか。','～のようだ',['～ない','～だろう','～ましょう'],['たとえを言うときに使います。','「まるで ～ のようだ」の形で使います。'],'「まるで」は、「～のようだ」というたとえの言い方と、いっしょに使います。');
  add('grammar','advanced','「おそらく」と合う、文の終わり方はどれですか。','～だろう',['～ない','～ましょう','～ください'],['はっきりとは言えない、予想を表します。','「おそらく ～ だろう」の形で使います。'],'「おそらく」は、「～だろう」という予想の言い方と、いっしょに使います。');
  add('grammar','advanced','「どうか」と合う、文の終わり方はどれですか。','～ください',['～ない','～だろう','～ようだ'],['人にお願いをするときに使います。','「どうか ～ ください」の形で使います。'],'「どうか」は、「～ください」というお願いの言い方と、いっしょに使います。');
  add('grammar','advanced','「たとえ」と合う、文の終わり方はどれですか。','～ても',['～ない','～ましょう','～だろう'],['「もしそうでも」という意味です。','「たとえ ～ ても」の形で使います。'],'「たとえ」は、「～ても」という言い方と、いっしょに使います。');
  add('grammar','advanced','「この本のよいところは、絵が多い（　）。」主語と述語が合うようにするには、何を入れますか。','ことです',['から','のに','ので'],['「よいところは」に対応する終わり方を考えます。','「～は、～ことです」の形にします。'],'主語の「よいところは」に対応するように、「ことです」とします。');
  add('grammar','advanced','「雪が ふって いる。」を文節に分けると、いくつになりますか。','三つ',['二つ','四つ','五つ'],['文節は、「ネ」を入れて切れるところで分けます。','「雪が／ふって／いる」のように切ります。'],'「雪が／ふって／いる」の三つの文節に分けられます。',null,['三つ','3つ','３つ','三','3','３']);

  // ---- 表現の工夫：基礎8・標準12・発展8 ----
  add('rhetoric','basic','「雪は、白いじゅうたんのようだ。」には、どんな表現の工夫が使われていますか。','直喩',['隠喩','擬人法','倒置'],['「ようだ」を使って、何かにたとえています。','「ようだ」「みたいだ」を使うたとえです。'],'「ようだ」を使って、たとえる表現を、直喩といいます。',null,['ちょくゆ','直喩']);
  add('rhetoric','basic','「雪は、白いじゅうたんだ。」には、どんな表現の工夫が使われていますか。','隠喩',['直喩','擬人法','体言止め'],['「ようだ」「みたいだ」を使っていません。','「～は、～だ」と、言い切ってたとえています。'],'「ようだ」などを使わずに、言い切ってたとえる表現を、隠喩といいます。',null,['いんゆ','隠喩']);
  add('rhetoric','basic','「風が、ささやく。」には、どんな表現の工夫が使われていますか。','擬人法',['直喩','隠喩','倒置'],['風は、人間のように、何をしていますか。','人でないものを、人のように表しています。'],'人でないものを、人のように表す表現を、擬人法といいます。',null,['ぎじんほう','擬人法']);
  add('rhetoric','basic','「ざあざあ」「ごろごろ」のように、音をまねて表した言葉を、何といいますか。','擬音語',['擬態語','擬人法','体言止め'],['実際に聞こえる音を、言葉にしています。','雨や雷の音を思いうかべましょう。'],'音や声をまねて表した言葉を、擬音語といいます。',null,['ぎおんご','擬音語']);
  add('rhetoric','basic','「きらきら」「ふわふわ」のように、ようすを感じを出して表した言葉を、何といいますか。','擬態語',['擬音語','擬人法','体言止め'],['音ではなく、ようすを表しています。','光り方やふんわりした感じを言葉にしています。'],'ようすや気持ちを、感じを出して表した言葉を、擬態語といいます。',null,['ぎたいご','擬態語']);
  add('rhetoric','basic','「夜の海。静かな、波の音。」のように、文の終わりを名詞で止める表現を、何といいますか。','体言止め',['倒置','反復','対句'],['「名詞」のことを、「体言」ともいいます。','文を、名詞で終えています。'],'文の終わりを、名詞で止める表現を、体言止めといいます。');
  add('rhetoric','basic','「走れ、ぼくの足よ。」のように、ふつうの語順を入れかえる表現を、何といいますか。','倒置',['反復','体言止め','直喩'],['ふつうは、「ぼくの足よ、走れ。」の順です。','言葉の順序を、入れかえています。'],'ふつうの語順を入れかえて、強調する表現を、倒置といいます。',null,['とうち','倒置']);
  add('rhetoric','basic','「ありがとう、ありがとう。」のように、同じ言葉をくり返す表現を、何といいますか。','反復',['倒置','体言止め','擬人法'],['同じ言葉を、何回も使っています。','気持ちを強める効果があります。'],'同じ言葉をくり返す表現を、反復といいます。',null,['はんぷく','反復']);

  add('rhetoric','standard','「木の葉が、おどる。」には、どんな表現の工夫が使われていますか。','擬人法',['直喩','隠喩','体言止め'],['木の葉は、人間のように、何をしていますか。','人でないものを、人のように表しています。'],'木の葉を、人のように「おどる」と表しているので、擬人法です。');
  add('rhetoric','standard','「かれは、ライオンだ。」には、どんな表現の工夫が使われていますか。','隠喩',['直喩','擬人法','倒置'],['「ようだ」を使っていません。','「かれ」を「ライオン」にたとえています。'],'「ようだ」を使わずに、言い切ってたとえているので、隠喩です。');
  add('rhetoric','standard','「月は、まるで、お盆のようだ。」には、どんな表現の工夫が使われていますか。','直喩',['隠喩','擬人法','体言止め'],['「ようだ」を使っています。','月を「お盆」にたとえています。'],'「ようだ」を使って、たとえているので、直喩です。');
  add('rhetoric','standard','「寒い、寒い、冬の朝。」には、どんな表現の工夫が使われていますか。','反復',['倒置','擬人法','直喩'],['同じ言葉が出てきます。','寒さを、強く印象づけています。'],'「寒い」をくり返して、寒さを強調しているので、反復です。');
  add('rhetoric','standard','「行こう、いっしょに。」には、どんな表現の工夫が使われていますか。','倒置',['反復','直喩','隠喩'],['ふつうの語順は、「いっしょに行こう。」です。','言葉の順序が、入れかわっています。'],'ふつうの語順をかえて、「いっしょに」を強めているので、倒置です。');
  add('rhetoric','standard','「山は高く、海は深い。」のように、二つの文を同じ形でならべる表現を、何といいますか。','対句',['倒置','体言止め','擬人法'],['「山は高く」と「海は深い」の形を見くらべます。','リズムをよくする効果があります。'],'同じ形の言葉を、ならべて使う表現を、対句といいます。',null,['ついく','対句']);
  add('rhetoric','standard','「雪が、ひらひらと、まい落ちる。」の「ひらひら」は、何といいますか。','擬態語',['擬音語','擬人法','体言止め'],['雪がまい落ちる、ようすを表しています。','音ではなく、ようすを、感じを出して表した言葉です。'],'「ひらひら」は、雪がまい落ちるようすを表す、擬態語です。',null,['ぎたいご','擬態語']);
  add('rhetoric','standard','体言止めを使うと、どんな効果がありますか。','あとに、よいんが残る',['事実を、細かく説明する','文を、長くする','強く、おしつける'],['文を、名詞で、切るとどうなるでしょう。','言い切らないことで、どんなふんいきになりますか。'],'体言止めは、文を言い切らず、あとによいんを残す効果があります。');
  add('rhetoric','standard','倒置を使うと、どんな効果がありますか。','伝えたいことを強める',['文を、長くする','事実を、細かく説明する','意味を、あいまいにする'],['最初に出てくる言葉は、どうなるでしょう。','語順を入れかえると、どんな印象がありますか。'],'倒置は、伝えたいことを、先に言うことで、強める効果があります。');
  add('rhetoric','standard','擬人法を使うと、どんな効果がありますか。','人のように感じさせ、親しみをもたせる',['むずかしく感じさせる','数字をはっきりさせる','文を短くする'],['人でないものを、人のように表します。','読む人の気持ちは、どうなるでしょう。'],'擬人法は、人でないものを、人のように表して、親しみやすい印象をあたえます。');
  add('rhetoric','standard','たとえ（比喩）を使うと、どんな効果がありますか。','ようすがわかりやすく、印象に残る',['事実が変わる','文が短くなる','意味がわからなくなる'],['ほかのものにたとえると、どうなるでしょう。','読む人が、思いうかべやすくなります。'],'たとえを使うと、ようすが、わかりやすくなり、印象に残ります。');
  add('rhetoric','standard','「ようだ」「みたいだ」を使わないでたとえる表現を、何といいますか。','隠喩',['直喩','擬人法','倒置'],['「雪は、白いじゅうたんだ。」のような言い方です。','「ようだ」を使うほうは、直喩といいます。'],'「ようだ」などを使わずに、言い切ってたとえる表現を、隠喩といいます。');

  add('rhetoric','advanced','「雪は、天からふる手紙である。」には、どんな表現の工夫が使われていますか。','隠喩',['直喩','擬人法','倒置'],['雪を、手紙にたとえています。','「ようだ」を使わずに、言い切っています。'],'雪を「手紙」と言い切ってたとえているので、隠喩です。');
  add('rhetoric','advanced','「ストーブが、冬の夜に、あたたかく笑っている。」には、どんな表現の工夫が使われていますか。','擬人法',['直喩','隠喩','体言止め'],['ストーブは、人間のように、何をしていますか。','「笑っている」に注目します。'],'ストーブを、笑う人のように表しているので、擬人法です。');
  add('rhetoric','advanced','「ぴゅうぴゅう、風が鳴る。」の「ぴゅうぴゅう」は、何といいますか。','擬音語',['擬態語','擬人法','体言止め'],['実際に聞こえる音をまねています。','風の音です。'],'風の音をまねた言葉なので、擬音語です。');
  add('rhetoric','advanced','「ふわり、ふわり、雪がまう。」で、ようすを表す言葉（擬態語）はどれですか。','ふわり',['雪','まう','が'],['雪がまうようすを、感じを出して表した言葉です。','「ふわり」はくり返されています。'],'「ふわり」は、雪がまうようすを表す擬態語です。くり返しているので、反復も使われています。');
  add('rhetoric','advanced','「春。それは、命の始まり。」の終わりには、どんな表現の工夫が使われていますか。','体言止め',['倒置','対句','擬人法'],['文の終わりが、「始まり」という名詞です。','言い切らず、あとによいんを残しています。'],'文の終わりが名詞で止まっているので、体言止めです。');
  add('rhetoric','advanced','「見たか、あの雪の景色を。」には、どんな表現の工夫が使われていますか。','倒置',['反復','直喩','対句'],['ふつうの語順は、「あの雪の景色を見たか。」です。','「見たか」が先に出ています。'],'ふつうの語順をかえているので、倒置です。');
  add('rhetoric','advanced','「天は高く、地は深い。」には、どんな表現の工夫が使われていますか。','対句',['隠喩','擬人法','体言止め'],['二つの文が、同じ形でならんでいます。','言葉の形が、そろっています。'],'同じ形の言葉をならべているので、対句です。');
  add('rhetoric','advanced','「かのじょの笑顔は、太陽のようだ。」と「かのじょの笑顔は、太陽だ。」のちがいは何ですか。','「ようだ」を使っているか、どうか',['どちらも同じ表現だ','人の顔が出ているか、どうか','ひらがなか、漢字か'],['二つの文の、言葉のちがいを見くらべます。','直喩と隠喩のちがいです。'],'前の文は「ようだ」を使った直喩、あとの文は言い切った隠喩です。');

  // ---- 物語文の読み取り：基礎8・標準12・発展8。短い文章を読んで答える ----
  function st(diff,passage,ask,answer,wrong,hints,explanation,inp){
    add('story',diff,'次の文章を読んで、問いに答えましょう。\n\n'+passage+'\n\n問い：'+ask,answer,wrong,hints,explanation,null,inp||null);
  }
  var P1='ぼくは毎朝、弟といっしょに雪かきをする。弟のたいちはまだ小さくて、スコップも重そうだ。それでも文句を言わず、一生けんめいに雪をはこんでいる。ある朝、ぼくが「もういいよ。」と言うと、たいちは首をふった。「兄ちゃんだって、まだやってるじゃないか。」ぼくは思わず笑ってしまった。';
  st('basic',P1,'ぼくは、毎朝、だれといっしょに雪かきをしていますか。','弟',['友だち','お父さん','近所の人'],['文章のはじめの文に注目します。','「いっしょに」の前に書かれています。'],'「ぼくは毎朝、弟といっしょに雪かきをする」と書かれています。',['おとうと','弟','たいち']);
  st('basic',P1,'たいちのようすとして、合っているのはどれですか。','小さくて、スコップも重そうだ',['大きくて、力もちだ','文句ばかり言っている','雪かきが、すきではない'],['文章の二つ目の文に注目します。','三つ目の文もヒントです。'],'「たいちはまだ小さくて、スコップも重そうだ」と書かれています。');
  st('standard',P1,'たいちが、首をふったのは、なぜですか。','兄がまだやっているのに、自分だけやめるわけにはいかないと思ったから',['雪かきが、楽しくなったから','兄にしかられたから','つかれて、動けなかったから'],['たいちの言葉に注目します。','「兄ちゃんだって」という言い方から、気持ちを考えます。'],'たいちは、「兄ちゃんだって、まだやってるじゃないか」と言っているので、兄がやっているのに自分だけやめられないと思ったのです。');
  st('advanced',P1,'さいごに、ぼくが「笑ってしまった」のは、どんな気持ちからですか。','弟の言い返しに、おどろきとほほえましさを感じたから',['弟をばかにしたから','雪かきがおもしろかったから','弟がまちがえたから'],['たいちは、小さいのに、ぼくに何を言いましたか。','「思わず」は、自然に出てしまうようすです。'],'小さな弟がしっかり言い返したことに、おどろきと、ほほえましさを感じて、思わず笑ったのです。');
  var P2='あすは、卒業式だ。ゆうなはいつものように、校庭の雪の上を歩いて教室に向かった。机もいすも、六年間と少しも変わらない。それなのに、きょうだけはなぜかちがって見えた。黒板に、小さく「ありがとう」と書いてみる。ふり返ると、窓の外で雪がしずかにふり出していた。';
  st('basic',P2,'卒業式は、いつですか。','あす',['きょう','来週','もう終わった'],['文章のはじめの文に注目します。','「あすは」と書かれています。'],'「あすは、卒業式だ」と書かれています。',['あす','あした','明日']);
  st('standard',P2,'「きょうだけはなぜかちがって見えた」のは、なぜだと考えられますか。','あすで最後だと思うと、教室が特別に感じられたから',['教室が、新しくなったから','雪がつもっていたから','先生がいなかったから'],['教室の机やいすは、どうでしたか。','あすは、何の日でしょう。'],'教室は六年間と変わらないのに、あすが卒業式だと思うと、特別に感じられたのです。');
  st('advanced',P2,'ゆうなが、黒板に「ありがとう」と書いたのは、どんな気持ちからだと考えられますか。','六年間の学校生活へのかんしゃの気持ち',['先生にしかられてくやしい気持ち','早く家に帰りたい気持ち','友だちへのいかり'],['「ありがとう」は、どんなときに言う言葉でしょう。','卒業式の前の日に、教室で書いています。'],'六年間を過ごした教室や学校生活への、かんしゃの気持ちが表れています。');
  st('advanced',P2,'さいごの「窓の外で雪がしずかにふり出していた」は、この場面にどんな効果をあたえていますか。','ゆうなの、しんとした気持ちを、静かに引き立てている',['急に天気が変わる、不安を表している','にぎやかなふんいきを作っている','ゆうなのいかりを表している'],['雪は、どんなふうにふり出していますか。','「しずかに」に注目します。'],'「しずかに」ふる雪は、ゆうなの、しんとした気持ちを、静かに引き立てています。');
  var P3='山小屋に着いたとき、あたりはすっかり暗くなっていた。おじいさんは何も聞かずに、ストーブに火を入れてくれた。冷えきった手足が、じんわりとほどけていく。しばらくして、おじいさんがぼそりと言った。「道に迷うのは、悪いことじゃない。そこから、どうするかだ。」ぼくはだまって、うなずいた。';
  st('basic',P3,'ぼくが山小屋に着いたとき、あたりはどんなようすでしたか。','すっかり暗くなっていた',['まだ明るかった','雪がふり始めていた','人でにぎわっていた'],['文章のはじめの文に注目します。','「あたりは」のあとに書かれています。'],'「あたりはすっかり暗くなっていた」と書かれています。');
  st('standard',P3,'おじいさんが、何も聞かずにストーブに火を入れてくれたのは、なぜだと考えられますか。','まず、ぼくの体をあたためさせたかったから',['ぼくを早くねかせたかったから','火を使うのが好きだから','ぼくにおこっていたから'],['ぼくの手足は、どんな状態でしたか。','「何も聞かずに」から、おじいさんの思いやりがわかります。'],'冷えきったぼくを、まずあたためようという、おじいさんの思いやりだと考えられます。');
  st('standard',P3,'「じんわりとほどけていく」は、どんなようすを表していますか。','冷えてかたまった体が、少しずつあたたまっていくようす',['急に体がいたくなるようす','手足がしびれてしまうようす','体が重くなるようす'],['「冷えきった手足」が、どうなっていくのでしょう。','「じんわり」は、少しずつ、広がるようすです。'],'冷えかたまった手足が、ストーブで少しずつあたたまり、ゆるんでいくようすを表しています。');
  st('advanced',P3,'おじいさんの「道に迷うのは、悪いことじゃない。そこから、どうするかだ。」には、どんな考えがこめられていますか。','失敗しても、そこから立て直すことが大切だという考え',['道は、地図で調べるべきだという考え','迷ったら、すぐに助けをよぶべきだという考え','山には、ひとりで来てはいけないという考え'],['「悪いことじゃない」と言っています。','「そこから、どうするか」が大切だと言っています。'],'迷うこと自体は悪くなく、そのあと、どうするかが大切だ、という考えがこめられています。');
  var P4='帰り道、急にふぶきになった。前を歩くけいたの背中が、白くかすんでいく。「こっちだ。」けいたが、手をのばしてくれた。ぼくは、その手を強くにぎった。足もとの雪は深かったけれど、不思議とこわくはなかった。家の明かりが見えたとき、二人は同時に大きく息をはいた。';
  st('basic',P4,'帰り道に、急にどうなりましたか。','ふぶきになった',['雨がふり出した','日がしずんだ','雪がやんだ'],['文章のはじめの文に注目します。','「急に」のあとに書かれています。'],'「帰り道、急にふぶきになった」と書かれています。');
  st('standard',P4,'けいたが「手をのばしてくれた」のは、どんな気持ちからだと考えられますか。','ぼくを助けて、いっしょに帰りたいという気持ち',['ぼくにおいつかれたくない気持ち','ぼくを早く帰らせたい気持ち','手がつめたかった気持ち'],['ふぶきの中で、手をのばすのは、どんなときでしょう。','けいたの「こっちだ。」という声も、ヒントです。'],'ふぶきの中、けいたはぼくを助けて、いっしょに帰ろうとしてくれたのです。');
  st('standard',P4,'「不思議とこわくはなかった」のは、なぜだと考えられますか。','けいたと手をつないでいて、安心だったから',['ふぶきが、弱まったから','家がすぐ近くだったから','雪がやわらかかったから'],['ぼくは、けいたの手をどうしましたか。','「不思議と」とあるので、理由は雪の深さではありません。'],'けいたと手をつないでいることで、安心し、こわくなくなったのです。');
  st('advanced',P4,'二人が、「同時に大きく息をはいた」のは、どんな気持ちからですか。','ぶじに帰りついて、ほっとした気持ち',['けんかをしたくやしい気持ち','つかれて、もう歩けない気持ち','早く遊びたい気持ち'],['「家の明かりが見えたとき」と書かれています。','ふぶきの中を歩いて、きんちょうしていました。'],'ふぶきの中をぶじに帰りつき、きんちょうがとけて、ほっとした気持ちを表しています。');
  var P5='雪まつりの前の夜、りくはひとり会場に残っていた。つくった雪のとうが、昼間の日ざしで少しとけて、かたむいていた。「あすまでに、直すしかない。」りくは手ぶくろをはずして、素手で雪をおした。指先が、じんじんとしびれる。それでも、手を止めなかった。';
  st('basic',P5,'りくは、前の夜、どこに残っていましたか。','雪まつりの会場',['学校の教室','自分の家','雪山の山小屋'],['文章のはじめの文に注目します。','「前の夜」のあとに書かれています。'],'「雪まつりの前の夜、りくはひとり会場に残っていた」と書かれています。');
  st('standard',P5,'雪のとうが、かたむいていたのは、なぜですか。','昼間の日ざしで、少しとけたから',['りくがぶつかったから','風がふいたから','雪がふったから'],['とうがかたむく前のようすに注目します。','「昼間の日ざしで」と書かれています。'],'「昼間の日ざしで少しとけて、かたむいていた」と書かれています。');
  st('standard',P5,'りくが、「手ぶくろをはずして」雪をおしたのは、どんな気持ちからだと考えられますか。','細かいところまで、手で確かめて、きちんと直したい気持ち',['手をあたためたい気持ち','早く帰りたい気持ち','雪をさわりたくない気持ち'],['手ぶくろをはずすと、何がしやすくなるでしょう。','指先がしびれるほど、がんばっています。'],'素手で雪にふれて、細かいところまで確かめながら、きちんと直したいという気持ちだと考えられます。');
  st('advanced',P5,'「それでも、手を止めなかった」には、りくのどんな気持ちが表れていますか。','指先のいたみをこえて、最後まで直しつづける強い気持ち',['もう、あきらめた気持ち','だれかに、見てほしい気持ち','しかられたくない気持ち'],['「それでも」の前に書かれていることを考えます。','指先は、どうなっていますか。'],'指先がしびれても、手を止めないので、最後まで直しつづける強い気持ちが表れています。');
  var P6='おばあちゃんから、手紙がとどいた。「雪がとけたら、ひさしぶりにうちにおいで。」ていねいな細い字だった。ぼくはふうとうをそっと、机のひき出しにしまった。雪がとけるまでは、あと一か月ほど。カレンダーに、小さく丸をつけた。';
  st('basic',P6,'おばあちゃんは、手紙で、何を伝えましたか。','雪がとけたら、うちに来てほしいこと',['雪がふったら、遊びに行くこと','お金を送ってほしいこと','ぼくの誕生日を祝うこと'],['手紙の中の、かぎ（「　」）の部分を読みます。','おばあちゃんが、ぼくにおねがいしていることです。'],'手紙には、「雪がとけたら、ひさしぶりにうちにおいで。」と書かれていました。');
  st('standard',P6,'手紙の字が「ていねいな細い字」と書かれているのは、なぜだと考えられますか。','おばあちゃんが、心をこめて書いたことが伝わるから',['おばあちゃんが、いそいでいたから','おばあちゃんが、おこっていたから','ぼくが、読みにくかったから'],['字のようすから、書いた人の気持ちがわかります。','「ていねいな」とは、どんなときに使う言葉でしょう。'],'ていねいな字から、おばあちゃんが、心をこめて手紙を書いたことが伝わってきます。');
  st('standard',P6,'ぼくが、手紙を「そっと、机のひき出しにしまった」のは、どんな気持ちからですか。','おばあちゃんからの手紙を、大切にしたい気持ち',['手紙をかくしたい気持ち','手紙がきらいな気持ち','手紙をなくしたい気持ち'],['「そっと」には、どんな気持ちがこもっているでしょう。','大切なものを、あつかうときの動作です。'],'「そっと」しまったのは、おばあちゃんからの手紙を、大切にしたかったからです。');
  st('advanced',P6,'ぼくが、カレンダーに「小さく丸をつけた」のは、どんな気持ちを表していますか。','おばあちゃんに会える日を、楽しみにしている気持ち',['手紙をすてたい気持ち','おばあちゃんの家に行きたくない気持ち','雪がとけるのをおそれる気持ち'],['雪がとけるのは、いつでしょう。','丸をつけるのは、どんな日ですか。'],'雪がとけたあとに、おばあちゃんの家に行くのが楽しみで、その日を待っている気持ちを表しています。');
  var P7='春の気配が、近づいてきた。校庭の雪が、まだらにとけていく。その下から、うすい緑色の小さな芽が、顔をのぞかせた。だれかが、「あ、芽だ！」と声をあげる。みんなが集まってきて、しゃがみこんだ。ずっと雪の下で待っていたのだと思うと、ぼくはその小さな芽が、いとおしくなった。';
  st('basic',P7,'とけた雪の下から、何が顔を出しましたか。','小さな芽',['小さな虫','小さな花','小さな石'],['文章の三つ目の文に注目します。','「その下から」のあとに書かれています。'],'「その下から、うすい緑色の小さな芽が、顔をのぞかせた」と書かれています。',['め','芽','小さな芽']);
  st('standard',P7,'みんなが、しゃがみこんだのは、なぜですか。','芽を、近くで見たかったから',['かくれたかったから','つかれたから','雪をほりたかったから'],['だれかが、「あ、芽だ！」と声をあげたあとです。','みんなの視線は、どこに向いていますか。'],'「芽だ！」という声を聞いて、みんなが小さな芽を、近くで見ようと、しゃがみこんだのです。');
  st('standard',P7,'「いとおしくなった」とは、どんな気持ちですか。','大切に思い、かわいがりたい気持ち',['にくらしい気持ち','おそろしい気持ち','おかしい気持ち'],['ぼくは、「ずっと雪の下で待っていた」と思っています。','小さな芽を、どう思ったのでしょう。'],'「いとおしい」は、大切に思い、かわいがりたい気持ちのことです。');
  st('advanced',P7,'この文章は、どんな季節の変わり目を表していますか。','冬から春へ',['春から夏へ','夏から秋へ','秋から冬へ'],['雪が、とけて、芽が出ています。','「春の気配が、近づいてきた」と書かれています。'],'雪がとけて、芽が顔を出しているので、冬から春へ変わるころを表しています。');

  // ---- 説明文の読み取り：基礎8・標準12・発展8。短い説明文を読んで答える ----
  function ex(diff,passage,ask,answer,wrong,hints,explanation,inp){
    add('explain',diff,'次の文章を読んで、問いに答えましょう。\n\n'+passage+'\n\n問い：'+ask,answer,wrong,hints,explanation,null,inp||null);
  }
  var E1='ふった雪は、時間がたつと、少しずつかたくしまっていく。雪のけっしょうがくずれて丸くなり、すき間が小さくなるからだ。新しい雪はふんわりして軽い。しかし、積もって一か月もたつと、重さが二倍以上になることもある。屋根に雪が積もったとき雪おろしを急ぐのは、このためである。';
  ex('basic',E1,'新しい雪は、どんなようすですか。','ふんわりして、軽い',['かたくて、重い','つぶが大きい','氷のようにすきとおっている'],['文章の三つ目の文に注目します。','「新しい雪は」のあとに書かれています。'],'「新しい雪はふんわりして軽い」と書かれています。');
  ex('standard',E1,'雪が、時間がたつとかたくしまっていくのは、なぜですか。','けっしょうがくずれて丸くなり、すき間が小さくなるから',['雪の上に、新しい雪がふるから','雪に、水がしみこむから','気温が下がるから'],['文章の二つ目の文に注目します。','「からだ。」の前に、理由が書かれています。'],'「雪のけっしょうがくずれて丸くなり、すき間が小さくなるからだ」と書かれています。');
  ex('standard',E1,'「このため」は、何をさしていますか。','積もった雪が、時間がたつと重くなること',['屋根に雪が積もること','新しい雪が軽いこと','雪おろしをすること'],['「このため」の前の文を読み直しましょう。','「重さが二倍以上になる」ことを、さしています。'],'「このため」は、積もった雪が、時間がたつと重くなることをさしています。');
  ex('advanced',E1,'雪おろしを急ぐ理由として、この文章から読み取れることは何ですか。','雪が時間とともに重くなり、屋根にかかる重さが大きくなるから',['雪が、すぐにとけてしまうから','近所の人が、見ているから','雪が、白く見えにくくなるから'],['雪は、積もったあと、どう変わりますか。','屋根にとって、雪が重くなるとどうなるでしょう。'],'積もった雪は、時間がたつと重くなるので、屋根にかかる重さが大きくなる前に、雪おろしを急ぎます。');
  var E2='雪の多い地方の道路には、「スノーシェッド」という、トンネルのようなおおいが作られている。これは、なだれやふきだまりから、車を守るためのものだ。屋根の部分は、積もった雪の重さにもたえられるよう、じょうぶに作られている。冬の間も安全に道路を使えるのは、こうした工夫のおかげである。';
  ex('basic',E2,'「スノーシェッド」とは、何ですか。','道路に作られた、トンネルのようなおおい',['雪をとかす機械','雪の多い地方の家','雪を運ぶトラック'],['文章のはじめの文に注目します。','「という」の前後に書かれています。'],'「スノーシェッド」は、道路に作られた、トンネルのようなおおいです。');
  ex('standard',E2,'スノーシェッドは、何から車を守るためのものですか。','なだれやふきだまり',['雨や風','ほこり','落ち葉'],['文章の二つ目の文に注目します。','「これは、」のあとに書かれています。'],'「なだれやふきだまりから、車を守るためのものだ」と書かれています。');
  ex('standard',E2,'屋根の部分が、じょうぶに作られているのは、なぜですか。','積もった雪の重さにたえるため',['車が、のぼれるようにするため','景色を見やすくするため','風を通しやすくするため'],['文章の三つ目の文に注目します。','「よう」の前に、理由が書かれています。'],'「積もった雪の重さにもたえられるよう、じょうぶに作られている」と書かれています。');
  ex('advanced',E2,'「こうした工夫」とは、何をさしていますか。','雪から道路を守る、スノーシェッドのようなしくみ',['雪を、遠くへ運ぶこと','雪に、色をつけること','車に、チェーンをつけること'],['「こうした」は、前に述べたことをさしています。','スノーシェッドの説明を、読み直しましょう。'],'「こうした工夫」は、スノーシェッドなど、雪から道路を守るしくみをさしています。');
  var E3='雪をためて、その冷たさを利用する「雪室」がある。雪室の中は、一年中温度が低く、しつ度も高い。そのため、野菜やお米を保存すると、味がよくなるといわれている。冷蔵庫のように電気を使わないので、環境にもやさしい。ただし、雪を集めて運ぶのには、手間がかかる。';
  ex('basic',E3,'「雪室」とは、何ですか。','雪をためて、その冷たさを利用する場所',['雪でできた家','雪をとかす機械','雪を運ぶ車'],['文章のはじめの文に注目します。','「雪室」という言葉の説明が書かれています。'],'「雪をためて、その冷たさを利用する『雪室』がある」と書かれています。');
  ex('basic',E3,'雪室の中の温度は、どうなっていますか。','一年中、低い',['夏だけ低い','冬だけ高い','日によって、大きく変わる'],['文章の二つ目の文に注目します。','「一年中」と書かれています。'],'「雪室の中は、一年中、温度が低く」と書かれています。');
  ex('standard',E3,'野菜やお米を、雪室で保存すると、どうなるといわれていますか。','味がよくなる',['形が変わる','すぐにくさる','色が白くなる'],['「そのため」のあとに注目します。','保存したものの味が、どうなるのでしょう。'],'「野菜やお米を保存すると、味がよくなるといわれている」と書かれています。');
  ex('advanced',E3,'「ただし」のあとには、何が書かれていますか。','雪室の、よくない点（手間がかかること）',['雪室の、よい点','雪室の、作り方','雪室の、歴史'],['「ただし」は、前のことに、条件や例外を足す言葉です。','「手間がかかる」と書かれています。'],'「ただし」のあとには、雪を集めて運ぶのに手間がかかる、という、よくない点が書かれています。');
  var E4='コウテイペンギンは、南極のきびしい寒さの中で、子育てをする。オスはたまごを足の上にのせておなかの皮でおおい、二か月ほど何も食べずに守りつづける。ふぶきの日には、たくさんのオスが、おしくらまんじゅうのように集まる。外側と内側がゆっくり入れかわることで、みんながあたたかさを分け合っているのだ。';
  ex('basic',E4,'コウテイペンギンが、子育てをする場所は、どこですか。','南極',['北極','日本','海の中'],['文章のはじめの文に注目します。','「きびしい寒さの中で」と書かれています。'],'「コウテイペンギンは、南極のきびしい寒さの中で、子育てをする」と書かれています。');
  ex('standard',E4,'ふぶきの日に、オスたちは、どうしますか。','たくさん集まって、おしくらまんじゅうのようになる',['ひとりずつ、はなれてじっとする','海に入って、さかなをとる','巣を遠くへ引っこす'],['文章の三つ目の文に注目します。','「ふぶきの日には、」のあとに書かれています。'],'「ふぶきの日には、たくさんのオスが、おしくらまんじゅうのように集まる」と書かれています。');
  ex('advanced',E4,'外側と内側が入れかわるのは、なぜだと考えられますか。','寒い外側にいる者が、交代であたたまれるようにするため',['集まった数をかぞえるため','えさを見つけやすくするため','ねむりやすくするため'],['外側と内側では、どちらが寒いでしょう。','文章のさいごに、「あたたかさを分け合っている」とあります。'],'寒い外側にいる者が、ずっと寒さにさらされないように、交代で、内側のあたたかい所に入ると考えられます。');
  ex('advanced',E4,'この文章の中心は、何ですか。','ペンギンが、助け合って、寒さをしのいでいること',['ペンギンが、えさをとること','ペンギンの、体の大きさ','ペンギンが、海をおよぐこと'],['文章のさいごの文に注目します。','全体を一文でまとめてみましょう。'],'この文章は、ペンギンが、たまごを守るため、あたたかさを分け合って寒さをしのいでいることを説明しています。');
  var E5='天気予報は、気象衛星や地上の観測所から集めたたくさんのデータをもとに作られる。雲の動きや気温、風の向きなどをコンピューターで計算して、これから先の天気を予想する。それでも予報が外れることがあるのは、自然がとても複雑だからである。予報はあくまで予想であって、百パーセント当たるとはかぎらない。';
  ex('basic',E5,'天気予報は、何をもとに作られますか。','気象衛星や観測所から集めた、たくさんのデータ',['昔の天気のきろく','人の感覚','その日の気温だけ'],['文章のはじめの文に注目します。','「をもとに作られる」の前に書かれています。'],'「気象衛星や、地上の観測所から集めた、たくさんのデータをもとに作られる」と書かれています。');
  ex('standard',E5,'コンピューターでは、何を計算しますか。','雲の動きや気温、風の向きなど',['明日の予定','買い物のお金','電車の時間'],['文章の二つ目の文に注目します。','「コンピューターで計算して」の前に書かれています。'],'「雲の動きや気温、風の向きなどをコンピューターで計算して」と書かれています。');
  ex('standard',E5,'予報が外れることがあるのは、なぜですか。','自然がとても複雑だから',['コンピューターが、こわれるから','データが、少ないから','人が、まちがえるから'],['「それでも」のあとの文に注目します。','「からである」の前に、理由が書かれています。'],'「自然がとても複雑だからである」と書かれています。');
  ex('advanced',E5,'筆者がいちばん言いたいことは、何ですか。','天気予報は予想であり、かならず当たるとはかぎらないということ',['天気予報は、むだだということ','天気は、予想できないということ','コンピューターは、まちがえないということ'],['文章のさいごの文に注目します。','「あくまで予想」と述べています。'],'さいごの文に、「予報はあくまで予想であって、百パーセント当たるとはかぎらない」とまとめられています。');
  var E6='地球の気温が上がると、氷河や極地の氷がとけて、海に流れこむ。すると、海の水が増えて、海面が上がる。海面が上がると、低い土地の島や町が、しずんでしまうおそれがある。そのため、世界中で、二酸化炭素を減らす取り組みが進められている。';
  ex('basic',E6,'地球の気温が上がると、氷河や極地の氷は、どうなりますか。','とけて、海に流れこむ',['もっと厚くなる','雪になる','空にのぼる'],['文章のはじめの文に注目します。','「地球の気温が上がると、」のあとに書かれています。'],'「氷河や極地の氷がとけて、海に流れこむ」と書かれています。');
  ex('standard',E6,'海面が上がると、どんなおそれがありますか。','低い土地の島や町が、しずんでしまうおそれ',['海の水が、冷たくなるおそれ','雪が、ふらなくなるおそれ','魚が、ふえるおそれ'],['文章の三つ目の文に注目します。','「おそれがある」の前に書かれています。'],'「低い土地の島や町が、しずんでしまうおそれがある」と書かれています。');
  ex('standard',E6,'「そのため」は、何をさしていますか。','海面が上がって、低い土地がしずむおそれがあること',['地球の気温が上がること','二酸化炭素が増えること','氷河がとけること'],['「そのため」の前の文を読み直しましょう。','あとの文の理由が、書かれています。'],'「そのため」は、海面が上がって、低い土地がしずむおそれがあることをさしています。');
  ex('advanced',E6,'世界中で、二酸化炭素を減らす取り組みが進められているのは、何のためですか。','気温が上がるのをおさえ、海面が上がるのをふせぐため',['魚を、ふやすため','雪を、早くとかすため','船を、はやく走らせるため'],['文章全体の流れを、たどりましょう。','気温が上がると、何が起こるのでしたか。'],'二酸化炭素を減らして、気温が上がるのをおさえ、海面が上がるのをふせぐためです。');
  var E7='なぜ雪は、白く見えるのだろう。雪は、もともとすきとおった氷のつぶが、たくさん集まったものだ。つぶの表面で、光があらゆる方向にはね返される。その光がわたしたちの目に入ると、白く見えるのだ。くだいた氷が白く見えるのも、同じ理由である。';
